BEGIN;
ALTER TABLE users ADD COLUMN IF NOT EXISTS email_verified_at TIMESTAMPTZ;
CREATE TABLE IF NOT EXISTS email_verification_tokens(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,business_id BIGINT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,user_id BIGINT NOT NULL,token_hash VARCHAR(128) NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,used_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),FOREIGN KEY(business_id,user_id) REFERENCES users(business_id,id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS email_verification_tokens_expires_idx ON email_verification_tokens(expires_at);
CREATE TABLE IF NOT EXISTS expenses(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,business_id BIGINT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,branch_id BIGINT NOT NULL,category VARCHAR(100) NOT NULL,description VARCHAR(255) NOT NULL,amount NUMERIC(14,2) NOT NULL CHECK(amount>0),payment_method VARCHAR(30) NOT NULL DEFAULT 'cash' CHECK(payment_method IN('cash','mobile_money','bank','other')),reference VARCHAR(120),expense_date DATE NOT NULL DEFAULT CURRENT_DATE,created_by BIGINT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),FOREIGN KEY(business_id,branch_id) REFERENCES branches(business_id,id),FOREIGN KEY(business_id,created_by) REFERENCES users(business_id,id));
CREATE TABLE IF NOT EXISTS ai_actions(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,business_id BIGINT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,branch_id BIGINT NOT NULL,user_id BIGINT NOT NULL,action_name VARCHAR(80) NOT NULL,payload JSONB NOT NULL DEFAULT '{}'::jsonb,status VARCHAR(20) NOT NULL DEFAULT 'pending',result JSONB,confirmation_token_hash VARCHAR(128) UNIQUE,expires_at TIMESTAMPTZ NOT NULL DEFAULT NOW()+INTERVAL '10 minutes',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),executed_at TIMESTAMPTZ,FOREIGN KEY(business_id,branch_id) REFERENCES branches(business_id,id),FOREIGN KEY(business_id,user_id) REFERENCES users(business_id,id));
CREATE INDEX IF NOT EXISTS expenses_business_branch_idx ON expenses(business_id,branch_id,expense_date DESC);
CREATE INDEX IF NOT EXISTS ai_actions_business_branch_idx ON ai_actions(business_id,branch_id,created_at DESC);
CREATE OR REPLACE FUNCTION dukaflow_touch_expenses() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=NOW();RETURN NEW;END $$;
DROP TRIGGER IF EXISTS expenses_updated_at_trigger ON expenses;CREATE TRIGGER expenses_updated_at_trigger BEFORE UPDATE ON expenses FOR EACH ROW EXECUTE FUNCTION dukaflow_touch_expenses();
DROP TRIGGER IF EXISTS dukaflow_assign_branch_expenses ON expenses;CREATE TRIGGER dukaflow_assign_branch_expenses BEFORE INSERT ON expenses FOR EACH ROW EXECUTE FUNCTION dukaflow_assign_branch_id();
ALTER TABLE expenses ENABLE ROW LEVEL SECURITY;ALTER TABLE expenses FORCE ROW LEVEL SECURITY;CREATE POLICY dukaflow_branch_isolation ON expenses USING(business_id=dukaflow_current_business_id() AND branch_id=dukaflow_current_branch_id()) WITH CHECK(business_id=dukaflow_current_business_id() AND branch_id=dukaflow_current_branch_id());
ALTER TABLE ai_actions ENABLE ROW LEVEL SECURITY;ALTER TABLE ai_actions FORCE ROW LEVEL SECURITY;CREATE POLICY dukaflow_branch_isolation ON ai_actions USING(business_id=dukaflow_current_business_id() AND branch_id=dukaflow_current_branch_id()) WITH CHECK(business_id=dukaflow_current_business_id() AND branch_id=dukaflow_current_branch_id());
COMMIT;
